export const LIA_HOOK_CONTEXT_BLOCK: string =
"// ── [RATIFY] — the direction matrix (doc 213 §4, as amended by doc 222 §3 and doc 224), as data ──\n//\n// Mirrors `directionFor` (hook-types.ts) row-for-row; that function is what\n// a report actually renders through. This table exists only so the byte-pin\n// test in tests/edge/run-li-assessment/doc213-hook-join.test.ts can catch\n// the two drifting apart. Rows 14–15 are the join's own rows (hook-join.ts):\n// the stored two-leg selection and nomination happen before `directionFor`.\n\nexport interface LiaHookMatrixRow {\n  readonly posture: string;\n  readonly fact_agreement: string;\n  readonly engine_verdict: string;\n  readonly shape: string;\n  readonly note: string;\n}\n\nexport const LIA_HOOK_DIRECTION_MATRIX: readonly LiaHookMatrixRow[] = [\n  {\n    posture: \"accepted\",\n    fact_agreement: \"same\",\n    engine_verdict: \"any\",\n    shape: \"S1 supports\",\n    note: \"hedged to `likely` language; never lifts a verdict (Law B3-9)\",\n  },\n  {\n    posture: \"accepted\",\n    fact_agreement: \"different / unknown\",\n    engine_verdict: \"any\",\n    shape: \"omit\",\n    note: \"nothing to say\",\n  },\n  {\n    posture: \"conditional\",\n    fact_agreement: \"same\",\n    engine_verdict: \"passes, and every condition_atom holds on the record\",\n    shape: \"S5b recognised + condition satisfied\",\n    note: \"the engine's pass is what satisfies the condition; the hook only echoes it (doc 222 §3)\",\n  },\n  {\n    posture: \"conditional\",\n    fact_agreement: \"same\",\n    engine_verdict: \"otherwise (fails / uncertain, or condition_atoms null / not all held)\",\n    shape: \"S5a recognised, condition unresolved\",\n    note: \"the guidance is relevant; whether its condition is met is Section {section}'s question — never asserted here (the doc 218 D1 defect)\",\n  },\n  {\n    posture: \"conditional\",\n    fact_agreement: \"different (a distinguishing pair holds)\",\n    engine_verdict: \"passes\",\n    shape: \"omit + assessor flag `authority_not_dispositive` (`rule_missing` when the pair expressly excludes)\",\n    note: \"a silent source under a pass is nothing missing; an express exclusion under a pass is the lawyer's rule\",\n  },\n  {\n    posture: \"conditional\",\n    fact_agreement: \"different (a distinguishing pair holds)\",\n    engine_verdict: \"fails / uncertain\",\n    shape: \"S6 source silent (S6x where the pair expressly excludes)\",\n    note: \"\\\"does not extend\\\" only from an authored `source_expressly_excludes` pair with a verified exclusion span (doc 222 §2.4)\",\n  },\n  {\n    posture: \"conditional\",\n    fact_agreement: \"unknown\",\n    engine_verdict: \"any\",\n    shape: \"omit\",\n    note: \"\",\n  },\n  {\n    posture: \"rejected\",\n    fact_agreement: \"same\",\n    engine_verdict: \"fails / uncertain\",\n    shape: \"S2 cuts against and applied\",\n    note: \"the verdict already reflects it\",\n  },\n  {\n    posture: \"rejected\",\n    fact_agreement: \"same\",\n    engine_verdict: \"passes\",\n    shape: \"omit + assessor flag `rule_missing`\",\n    note:\n      \"the lawyer's rule: an adverse authority on the same facts under a pass means a rule is missing — never printed as \\\"risk noted\\\"\",\n  },\n  {\n    posture: \"rejected\",\n    fact_agreement: \"different (a distinguishing pair holds)\",\n    engine_verdict: \"any\",\n    shape: \"S3 cuts against but distinguished\",\n    note: \"renders only from the pair (source fact / record fact); never from an atom's generic phrase\",\n  },\n  {\n    posture: \"rejected\",\n    fact_agreement: \"unknown\",\n    engine_verdict: \"any\",\n    shape: \"omit\",\n    note: \"\",\n  },\n  {\n    posture: \"contested (R4)\",\n    fact_agreement: \"same\",\n    engine_verdict: \"any\",\n    shape: \"S4 noted as a boundary\",\n    note: \"prints the derived status and the appeal note; no relation drawn\",\n  },\n  {\n    posture: \"contested (R4)\",\n    fact_agreement: \"different / unknown\",\n    engine_verdict: \"any\",\n    shape: \"omit\",\n    note: \"a contested decision on different facts adds nothing (doc 222 §3)\",\n  },\n  {\n    posture: \"any\",\n    fact_agreement: \"unknown from atoms\",\n    engine_verdict: \"—\",\n    shape: \"the stored two-leg selection's agreement, if one exists; else omit + flag `selection_pending`; legs disagreed → omit + flag `selection_unsettled` (the ROO item)\",\n    note: \"doc 224 §1: a call is made only where no stored decision exists AND the pre-filter says either answer could print\",\n  },\n  {\n    posture: \"any\",\n    fact_agreement: \"`required_atoms` not all held\",\n    engine_verdict: \"—\",\n    shape: \"not nominated\",\n    note: \"\",\n  },\n];\n\n// ── [RATIFY] — the atom-phrase map (doc 213 §5) ──────────────────────────\n//\n// One ratified clause per closed-list atom value in the hook vocabulary\n// (§0: `class:`, `flag:`, `relationship:`, `data_category:`, `instrument:`,\n// and the `state:intake.<path>=<value>` combinations a first hook batch is\n// likely to need — doc 213 §3's selection rule draws the first batch from\n// the same profiles as the already-ratified W1-W7 rules, so the `state:`\n// atoms below are exactly those rules' own trigger values). Every value\n// named in doc 213 §5's own text is reproduced verbatim; the rest (\"add the\n// others in the same register\") are this build's own drafting, listed in\n// full in 213A-TRACK-H2-BUILD-LOG-2026-09-07.md for the CEO's ratification\n// pass alongside the matrix and the shapes.\n\nexport const LIA_ATOM_PHRASES: Readonly<Record<string, string>> = {\n  // — classes (RULE_PRODUCT_REGISTRY.lia.typed_state_vocabulary.classes) —\n  \"class:fraud_prevention\": \"its processing is carried out for fraud prevention\",\n  \"class:direct_marketing\": \"its processing is carried out for direct marketing\",\n  \"class:employee_monitoring\": \"it monitors employees\",\n  \"class:behavioral_advertising\": \"its processing is for behavioural advertising\",\n  \"class:research_analytics\": \"its processing is for research or analytics\",\n  \"class:it_security\": \"its processing is for network and information security\",\n  \"class:product_improvement\": \"its processing is for product improvement\",\n  \"class:contractual_administration\": \"its processing is carried out for contractual administration\",\n\n  // — flags (RULE_PRODUCT_REGISTRY.lia.typed_state_vocabulary.flags) —\n  \"flag:children\": \"children are among the people affected\",\n  \"flag:special_category\": \"special-category data is processed\",\n  \"flag:eprivacy_terminal_equipment\": \"it accesses information stored on a user's device\",\n  \"flag:electronic_marketing\": \"its processing is for electronic marketing\",\n  \"flag:public_authority\": \"it is a public authority\",\n  \"flag:large_scale\": \"the processing is large-scale\",\n  \"flag:automated_decision\": \"the processing involves automated decision-making\",\n\n  // — relationships (RULE_PRODUCT_REGISTRY.lia.typed_state_vocabulary.relationships) —\n  \"relationship:employee\": \"the people affected are its employees\",\n  \"relationship:customer\": \"the people affected are its customers\",\n  \"relationship:prospect\": \"the people affected are its prospects\",\n  \"relationship:public\": \"the people affected are members of the public with no relationship to it\",\n\n  // — data categories (LIA_DATA_CATEGORIES / src/pages/LIAssessment.enums.ts DATA_CATEGORIES) —\n  \"data_category:Contact data\": \"it processes contact data\",\n  \"data_category:Purchase/transaction history\": \"it processes purchase or transaction history\",\n  \"data_category:Browsing/behavioural data\": \"it processes browsing or behavioural data\",\n  \"data_category:Location data\": \"it processes location data\",\n  \"data_category:Employment data\": \"it processes employment data\",\n  \"data_category:Financial data\": \"it processes financial data\",\n  \"data_category:Health or medical data\": \"it processes health or medical data\",\n  \"data_category:Biometric data\": \"it processes biometric data\",\n  \"data_category:Special category data\": \"it processes special-category data\",\n  \"data_category:Communications data\": \"it processes communications data\",\n  \"data_category:Device/technical data\": \"it processes device or technical data\",\n  \"data_category:Other\": \"it processes other categories of data not separately listed\",\n\n  // — instruments (RULE_PRODUCT_REGISTRY.lia.instrument_scope) —\n  \"instrument:EU GDPR\": \"its processing is assessed under the EU GDPR\",\n  \"instrument:UK GDPR\": \"its processing is assessed under the UK GDPR\",\n\n  // — state: atoms — ONE PHRASE PER CLOSED OPTION the hook drafter may emit.\n  // The drafter (generate-corpus-hooks/_local/vocabulary.ts, STATE_ATOM_ENUMS)\n  // admits exactly these `state:intake.` paths and option strings; a drafted\n  // hook holding an atom with no phrase here would fail at render as an\n  // `unresolved_slot` AFTER the drafting spend, so the map covers the whole\n  // closed vocabulary and tests/edge/corpus/doc213-vocabulary-phrase-coverage\n  // .test.ts pins the two sets to each other in both directions. Doc 213\n  // §5's own three examples are reproduced verbatim; the rest are this\n  // build's drafting in the same register, for the CEO's ratification pass.\n\n  // opt-out (intake.balancing_details.opt_out_available — three options)\n  \"state:intake.balancing_details.opt_out_available=No opt-out is available\": \"no opt-out is available\",\n  \"state:intake.balancing_details.opt_out_available=Yes — unconditional, on request, with no consequence\":\n    \"an unconditional opt-out is available\",\n  \"state:intake.balancing_details.opt_out_available=Yes — but conditional or subject to review\":\n    \"an opt-out is available only on conditions or subject to review\",\n\n  // interest type (intake.purpose_details.interest_type — the intake's eight\n  // closed options, LIAssessmentIntake.tsx \"What type of interest is this?\")\n  \"state:intake.purpose_details.interest_type=Commercial / revenue-related\": \"its interest is commercial or revenue-related\",\n  \"state:intake.purpose_details.interest_type=Operational / service delivery\": \"its interest is operational or concerns service delivery\",\n  \"state:intake.purpose_details.interest_type=Security / fraud prevention\": \"its interest is security or fraud prevention\",\n  \"state:intake.purpose_details.interest_type=Legal / regulatory compliance\": \"its interest is legal or regulatory compliance\",\n  \"state:intake.purpose_details.interest_type=Public interest / societal benefit\": \"its interest is a public interest or societal benefit\",\n  \"state:intake.purpose_details.interest_type=Research / product improvement\": \"its interest is research or product improvement\",\n  \"state:intake.purpose_details.interest_type=Political / electoral campaigning\": \"its interest is political or electoral campaigning\",\n  \"state:intake.purpose_details.interest_type=Other (describe below)\": \"its interest is of a kind it has described in its own words\",\n\n  // Article 9(2) condition (intake.balancing_details.art9_condition — twelve\n  // options; doc 206E field N1)\n  \"state:intake.balancing_details.art9_condition=Explicit consent (Art. 9(2)(a))\":\n    \"it relies on explicit consent as its Article 9(2) condition\",\n  \"state:intake.balancing_details.art9_condition=Employment, social security or social protection law (Art. 9(2)(b))\":\n    \"it relies on employment, social security or social protection law as its Article 9(2) condition\",\n  \"state:intake.balancing_details.art9_condition=Vital interests (Art. 9(2)(c))\":\n    \"it relies on vital interests as its Article 9(2) condition\",\n  \"state:intake.balancing_details.art9_condition=Not-for-profit body's legitimate activities (Art. 9(2)(d))\":\n    \"it relies on the legitimate activities of a not-for-profit body as its Article 9(2) condition\",\n  \"state:intake.balancing_details.art9_condition=Data manifestly made public by the individual (Art. 9(2)(e))\":\n    \"it relies on data manifestly made public by the individual as its Article 9(2) condition\",\n  \"state:intake.balancing_details.art9_condition=Legal claims or judicial acts (Art. 9(2)(f))\":\n    \"it relies on legal claims or judicial acts as its Article 9(2) condition\",\n  \"state:intake.balancing_details.art9_condition=Substantial public interest (Art. 9(2)(g))\":\n    \"it relies on substantial public interest as its Article 9(2) condition\",\n  \"state:intake.balancing_details.art9_condition=Health or social care (Art. 9(2)(h))\":\n    \"it relies on health or social care as its Article 9(2) condition\",\n  \"state:intake.balancing_details.art9_condition=Public health (Art. 9(2)(i))\":\n    \"it relies on public health as its Article 9(2) condition\",\n  \"state:intake.balancing_details.art9_condition=Archiving, research or statistics (Art. 9(2)(j))\":\n    \"it relies on archiving, research or statistics as its Article 9(2) condition\",\n  \"state:intake.balancing_details.art9_condition=None identified\":\n    \"it has identified no Article 9(2) condition for the special-category data\",\n  \"state:intake.balancing_details.art9_condition=Not yet assessed\":\n    \"the Article 9(2) condition for the special-category data has not yet been assessed\",\n\n  // necessity (intake.necessity_details.achievable_without_personal_data —\n  // three options; doc 206E field N6)\n  \"state:intake.necessity_details.achievable_without_personal_data=Yes — the purpose could be achieved without personal data, or with anonymised or synthetic data\":\n    \"it has recorded that the purpose could be achieved without personal data, or with anonymised or synthetic data\",\n  \"state:intake.necessity_details.achievable_without_personal_data=No — personal data is required (explain why below)\":\n    \"it has recorded that personal data is required for the purpose\",\n  \"state:intake.necessity_details.achievable_without_personal_data=Not assessed\":\n    \"whether the purpose could be achieved without personal data has not yet been assessed\",\n\n  // booleans the intake records directly (each `true` mirrors a flag above;\n  // the `false` forms are the only way to phrase an ABSENCE)\n  \"state:intake.balancing_details.special_category_data=true\": \"special-category data is processed\",\n  \"state:intake.balancing_details.special_category_data=false\": \"no special-category data is processed\",\n  \"state:intake.balancing_details.children_data_subjects=true\": \"children are among the people affected\",\n  \"state:intake.balancing_details.children_data_subjects=false\": \"children are not among the people affected\",\n\n  // direct-marketing channels (intake.purpose_details.marketing_channels.* —\n  // doc 206E field N4)\n  \"state:intake.purpose_details.marketing_channels.automated_calls=true\": \"it markets by automated calls\",\n  \"state:intake.purpose_details.marketing_channels.automated_calls=false\": \"it does not market by automated calls\",\n  \"state:intake.purpose_details.marketing_channels.live_calls=true\": \"it markets by live calls\",\n  \"state:intake.purpose_details.marketing_channels.live_calls=false\": \"it does not market by live calls\",\n  \"state:intake.purpose_details.marketing_channels.email_sms=true\": \"it markets by e-mail or SMS\",\n  \"state:intake.purpose_details.marketing_channels.email_sms=false\": \"it does not market by e-mail or SMS\",\n  \"state:intake.purpose_details.marketing_channels.post=true\": \"it markets by post\",\n  \"state:intake.purpose_details.marketing_channels.post=false\": \"it does not market by post\",\n  \"state:intake.purpose_details.marketing_channels.online_advertising=true\": \"it markets by online advertising\",\n  \"state:intake.purpose_details.marketing_channels.online_advertising=false\": \"it does not market by online advertising\",\n  \"state:intake.purpose_details.marketing_channels.none=true\": \"it uses no direct-marketing channel\",\n  \"state:intake.purpose_details.marketing_channels.none=false\": \"it uses at least one direct-marketing channel\",\n};\n\n// ── [RATIFY] — the sentence shapes (doc 213 §5 as amended by doc 222 §4 and,\n// 2026-09-09, PROMOTED to doc 238's paragraph-form shapes) ──────────────────\n//\n// PROMOTED 2026-09-09 (CEO ruling, this session): the clause-form shapes\n// below were replaced wholesale by what shipped for the rest of this session\n// as `LIA_HOOK_SHAPES_PROPOSED_2026_09` — doc 237 §5 found no shape, in any\n// product, could produce a CEO-approved hook paragraph (docs 223B/233/234/\n// 236 are all 4-7-sentence paragraphs built around a verbatim quoted clause,\n// a hedge, and a forward-looking section pointer; every shape shipped before\n// today was a 2-4-sentence clause). Every slot is still a record substring,\n// a ratified phrase, a ratified paraphrase, or a pair's authored facts, plus\n// the three new slots doc 238 added: {quote} (the verbatim, verified\n// `finding_span`, quoted by the template — quote marks are ratified template\n// text, never drafted content), {governing_provision} (unused by any LIA\n// shape — LIA's sources ARE its own governing law's authorities), and\n// {hedge} (a hook's own `hedge_sentence`, positioned where every approved\n// paragraph actually places it: before the forward-looking pointer and the\n// citation, never after — S1/S2 only, the \"matching\" shapes an approved\n// hedge ever sits on). NONE of this reproduces any specific ratified\n// paragraph byte-for-byte on its own — the four hooks whose EXACT ratified\n// prose doesn't fit even this generalised skeleton (0af0876d, 63bf2fe9,\n// 66742297, a22b1399; each hook's own \"Implementation note\" in doc 223B says\n// so) render through `AuthorityHook.literal_sentence_override` instead\n// (hook-types.ts), which bypasses this shape map entirely for that hook.\n// This promoted map is the DEFAULT path every other/future hook still uses.\n\nexport const LIA_HOOK_SHAPES: Readonly<Record<\"S1\" | \"S2\" | \"S3\" | \"S4\" | \"S5a\" | \"S5b\" | \"S6\" | \"S6x\", string>> = {\n  S1:\n    \"The company has stated that {customer_fact}. In {authority}, {regulator} {verb} that where {fact_pattern}, {finding} — in its own words, \\\"{quote}\\\". That finding supports the company's position on the {factor}. {hedge}Section {section} records that determination. ({citation}; {status}.)\",\n  S2:\n    \"The company has stated that {customer_fact}. In {authority}, {regulator} found that where {fact_pattern}, {finding} — in its own words, \\\"{quote}\\\". That finding cuts against the company's position on the {factor}. {hedge}Whether that holds on this record is addressed in Section {section}. ({citation}; {status}.)\",\n  S3:\n    \"In {authority}, {regulator} found that where {fact_pattern}, {finding} — in its own words, \\\"{quote}\\\". That finding turned on the fact that {source_fact}; on this record the company has instead stated that {record_fact}. The decision marks a boundary rather than a finding against the company. ({citation}; {status}.)\",\n  S4:\n    \"In {authority}, {regulator} found that where {fact_pattern}, {finding} — in its own words, \\\"{quote}\\\". The company has stated that {customer_fact}. That decision is {status}; it is noted as a boundary and is not applied. ({citation}.)\",\n  S5a:\n    \"In {authority}, {regulator} {verb} that {proposition} — in its own words, \\\"{quote}\\\" — subject to {condition}. That guidance is relevant to the company's asserted {factor}; whether its condition is satisfied is addressed in Section {section}. ({citation}; {status}.)\",\n  S5b:\n    \"In {authority}, {regulator} {verb} that {proposition} — in its own words, \\\"{quote}\\\" — subject to {condition}. That guidance is relevant to the company's asserted {factor}; whether its condition is satisfied is addressed in Section {section}. The facts identified in Section {section} satisfy that stated condition. ({citation}; {status}.)\",\n  S6:\n    \"The company has stated that {record_fact}. In {authority}, {regulator} {verb} that {proposition} — in its own words, \\\"{quote}\\\" — subject to {condition}, but does not address whether legitimate interests is available where {record_fact}. The conclusion in Section {section} therefore rests on the separately identified rules and facts, not on that guidance. ({citation}; {status}.)\",\n  S6x:\n    \"The company has stated that {record_fact}. In {authority}, {regulator} {verb} that {proposition} — in its own words, \\\"{quote}\\\" — subject to {condition}, and that {exclusion_paraphrase}; that exclusion applies to processing of the kind the company describes. Whether it applies here is addressed in Section {section}. ({citation}; {status}.)\",\n};\n\n// ── [RATIFY] — concept equivalence (doc 222 §2.3) ────────────────────────\n//\n// Two atoms naming the SAME underlying fact share a concept; the render\n// dedupes `{customer_fact}` by concept (the doc 218 D4 \"special-category\n// data is processed; it processes special-category data\" defect). This\n// table carries no legal meaning — only \"these two atoms say one thing\" —\n// which is why it may be generic where the withdrawn objected-phrase map\n// could not. An atom absent here is its own concept. NOTE (build deviation\n// from doc 222 §2.3's example table): the interest-type state atoms\n// \"Security / fraud prevention\" and \"Research / product improvement\" each\n// straddle two classes, so they are their own concepts rather than being\n// conflated with one class — under-deduping is the safe direction.\n\nexport const LIA_ATOM_CONCEPTS: Readonly<Record<string, string>> = {\n  \"flag:special_category\": \"special_category\",\n  \"data_category:Special category data\": \"special_category\",\n  \"state:intake.balancing_details.special_category_data=true\": \"special_category\",\n  \"flag:children\": \"children\",\n  \"state:intake.balancing_details.children_data_subjects=true\": \"children\",\n  \"class:direct_marketing\": \"direct_marketing\",\n  \"flag:electronic_marketing\": \"electronic_marketing\",\n  \"state:intake.purpose_details.marketing_channels.email_sms=true\": \"electronic_marketing\",\n};\n\n/** The concept an atom names — itself when the table has no entry. */\nexport function liaAtomConcept(atom: string): string {\n  return LIA_ATOM_CONCEPTS[atom] ?? atom;\n}\n\n// ── [RATIFY] — factor phrases (doc 222 §5): the `{factor}` slot, without a\n// leading article (every shape supplies \"the\") ──────────────────────────\n\nexport const LIA_FACTOR_PHRASES: Readonly<Record<string, string>> = {\n  \"Interest legitimacy\": \"legitimacy of its interest\",\n  \"Necessity and less-intrusive means\": \"necessity\",\n  \"Balancing of interests, rights and freedoms\": \"balance\",\n  \"Reasonable expectations of the data subject\": \"reasonable expectations\",\n  \"Potential harms and severity\": \"potential harms\",\n  \"Safeguards and mitigations\": \"safeguards\",\n  \"Relationship with the individual\": \"relationship with the people affected\",\n  \"Children's data\": \"children's data\",\n  \"Special-category and ePrivacy interplay\": \"special-category data and ePrivacy\",\n  \"Third-party interests\": \"third-party interests\",\n  \"Scale, frequency and duration\": \"scale\",\n};\n\n// ── [RATIFY] — source status labels (doc 222 §2.7) ───────────────────────\n//\n// The PRINTED status is derived from the source row at generate time\n// (`status_label`, dated where the source carries a date); these are the\n// undated fallbacks by `source_status`, and — for a v1 hook with no source\n// status at all — the legacy settledness labels. \"Settled law or adopted\n// guidance\" is withdrawn: it conflated binding law with interpretive\n// guidance (ChatGPT review of doc 221, adopted 2026-09-08).\n\nexport const LIA_SOURCE_STATUS_LABELS: Readonly<Record<string, string>> = {\n  edpb_guidelines_final: \"EDPB guidelines — interpretive guidance, not binding law\",\n  edpb_opinion: \"EDPB Article 64 opinion — Board opinion, not a judicial decision\",\n  wp29_opinion: \"Article 29 Working Party opinion — historical interpretive guidance\",\n  regulator_guidance: \"regulatory guidance — non-binding\",\n  sa_decision: \"supervisory-authority decision — persuasive, non-binding outside its jurisdiction\",\n  sa_decision_affirmed: \"supervisory-authority decision, affirmed on appeal\",\n  sa_decision_appeal_pending: \"under appeal\",\n};\n\n// ── RATIFIED by the CEO 2026-09-08 — the appeal sentence ─────────────────\n//\n// Where an appeal is known to have been made (`source_status` =\n// sa_decision_appeal_pending, derived at generate time from the source row's\n// appeal_status or the curation note), the join appends this sentence,\n// verbatim, after the hook's sentence. The appeal's particulars\n// (`appeal_note`: docket, date) are record-block data and are never printed.\n\nexport const LIA_APPEAL_SENTENCE = \"This matter is subject to an appeal which could invalidate this ruling.\";\n\nexport const LIA_SETTLEDNESS_LABELS: Readonly<Record<\"R1\" | \"R2\" | \"R3\" | \"R4\", string>> = {\n  R1: \"adopted guidance or settled authority\",\n  R2: \"a settled line of decisions\",\n  R3: \"a single supervisory authority's decision\",\n  R4: \"under appeal / contested\",\n};\n";
